        while r<h:
            col=grid[r][c]; j=r+1
            while j<h and grid[j][c]==col: j+=1
            if j-r>=4 and col!=bg: bars.append((j-r,col,'v',c,r,j))
            r=j
    if not bars: return out
    _, fill, orient, fixed, start, end=max(bars)
    # Find compact components; ignore guide and background. Use the object
    # aligned with the guide's direction, selected by smallest component area
    # among similarly shaped candidates and proximity to the long guide.
    seen=set(); comps=[]
    for r in range(h):
      for c in range(w):
        col=grid[r][c]
        if col in (bg,fill) or (r,c) in seen: continue
