            if 0<=yy<h and 0<=xx<w and grid[yy][xx]==col and (yy,xx) not in seen:
              seen.add((yy,xx)); q.append((yy,xx))
        comps.append((col,cells))
    # The examples' selected component is an L/irregular shape, not the long
    # bars; retain only components whose bounding extent exceeds 1 in both axes.
    candidates=[]
    for col,cells in comps:
      ys=[p[0] for p in cells]; xs=[p[1] for p in cells]
      if len(cells)>=3 and len(set(ys))>=2 and len(set(xs))>=2:
        candidates.append((col,cells))
    # Among motifs, the one at the extreme corner opposite the guide is selected.
    if candidates:
      def key(item):
        col,cells=item
        ys=[p[0] for p in cells]; xs=[p[1] for p in cells]
        return (min(ys)+min(xs) if orient=='h' else min(ys)+min(xs), -len(cells))
      col,cells=min(candidates,key=key)
      for r,c in cells: out[r][c]=fill
