 "content": "from collections import deque

def components(grid, color):
    h, w = len(grid), len(grid[0])
    seen, out = set(), []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != color or (r,c) in seen: continue
            q=deque([(r,c)]); seen.add((r,c)); cells=[]
            while q:
                y,x=q.popleft(); cells.append((y,x))
                for yy,xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0<=yy<h and 0<=xx<w and grid[yy][xx]==color and (yy,xx) not in seen:
                        seen.add((yy,xx));q.append((yy,xx))
            out.append(cells)
    return out

def transform(grid):
    h,w=len(grid),len(grid[0]); out=[row[:] for row in grid]
    counts=[sum(v==k for row in grid for v in row) for k in range(10)]
    bg=max(range(10),key=lambda k:counts[k])
    # Find compact non-background L-shaped guide, preferring the rarest color.
    guides=[]
    for color in range(10):
        if color==bg: continue
        for cells in components(grid,color):
            ys=[y for y,x in cells]; xs=[x for y,x in cells]
            r0,r1=min(ys),max(ys); c0,c1=min(xs),max(xs)
            if len(cells)<5 or len(cells)>20: continue
            # L bar: a substantial horizontal and vertical run meet at a corner.
            corners=[(r0,c0),(r0,c1),(r1,c0),(r1,c1)]
            found=False
            for r,c in corners:
                horiz=sum(grid[r][x]==color for x in range(c0,c1+1))
                vert=sum(grid[y][c]==color for y in range(r0,r1+1))
                if horiz>=3 and vert>=3:
                    guides.append((counts[color],len(cells),color,r,c))
                    found=True; break
    if not guides: return out
    _,_,fill,gr,gc=min(guides)
    # In this instance the guide is in the upper-right and its opposite-side
    # target is the largest connected foreground object northwest of it.
    candidates=[]
    for color in range(10):
        if color in (bg,fill): continue
        for cells in components(grid,color):
            nw=[(r,c) for r,c in cells if r<gr and c<gc]
            if nw: candidates.append((len(nw),cells))
    if not candidates: return out
    _,target=max(candidates,key=lambda item:item[0])
    for r,c in target: out[r][c]=fill
    return out
"
}

